package com.rustyledger;

public final class RustyLedger {

    private RustyLedger() {
    }

    public static Ledger openLedger() {
        return new Bank();
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class Bank implements Ledger {

    final Map<String, Account> accounts = new HashMap<>();
    final Map<String, BigDecimal> used = new HashMap<>();
    final Map<String, Transaction> txs = new LinkedHashMap<>();
    final Map<String, int[]> counts = new HashMap<>();
    final Fees fees = new Fees();
    final AuditLog audit = new AuditLog();
    int txSeq = 0;

    private final Engine engine;

    public Bank() {
        this.engine = new Engine(this);
    }

    public void openAccount(String id, String tier, String currency, String openingBalance) {
        if (id == null || id.trim().length() == 0 || id.indexOf('|') >= 0) {
            throw new IllegalArgumentException("INVALID ACCOUNT ID");
        }
        if (!"STANDARD".equals(tier) && !"PREMIUM".equals(tier) && !"STAFF".equals(tier)) {
            throw new IllegalArgumentException("INVALID TIER: " + tier);
        }
        if (!"PLN".equals(currency) && !"EUR".equals(currency) && !"USD".equals(currency)) {
            throw new IllegalArgumentException("INVALID CURRENCY: " + currency);
        }
        if (openingBalance == null || !openingBalance.matches("\\d+(\\.\\d{1,2})?")) {
            throw new IllegalArgumentException("INVALID AMOUNT: " + openingBalance);
        }
        if (accounts.containsKey(id)) {
            throw new IllegalStateException("ACCOUNT EXISTS: " + id);
        }
        accounts.put(id, new Account(tier, currency, new BigDecimal(openingBalance).setScale(2)));
    }

    public String balance(String id) {
        Account account = accounts.get(id);
        if (account == null) {
            throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + id);
        }
        return account.balance() + " " + account.currency();
    }

    public List<String> auditLog() {
        return audit.lines();
    }

    public String dailyReport(String date) {
        return DailyReport.build(counts, fees, date);
    }

    public String submit(String line) {
        return engine.submit(line);
    }
}

package com.rustyledger;

import java.math.BigDecimal;

public final class Account {

    private final String tier;
    private final String currency;
    private BigDecimal balance;

    public Account(String tier, String currency, BigDecimal balance) {
        this.tier = tier;
        this.currency = currency;
        this.balance = balance;
    }

    public String tier() {
        return tier;
    }

    public String currency() {
        return currency;
    }

    public BigDecimal balance() {
        return balance;
    }

    public void debit(BigDecimal amount, BigDecimal fee) {
        balance = balance.subtract(amount.add(fee));
    }

    public void credit(BigDecimal amount) {
        balance = balance.add(amount);
    }

    public void reverse(BigDecimal credited) {
        balance = balance.subtract(credited);
    }
}

