package com.rustyledger;

import java.math.BigDecimal;

final class InstructionParser {

    private InstructionParser() {
    }

    Instruction parse(String line) {
        if (line == null || line.trim().length() == 0) {
            return new Instruction("???", null, null, null, null, null, null, "BAD_INSTRUCTION", "empty instruction");
        }
        String[] fields = line.split("\\|", -1);
        String verb = fields[0];
        int wanted = fieldCount(verb);
        if (wanted < 0) {
            return new Instruction(verb, null, null, null, null, null, null, "BAD_INSTRUCTION", "unknown verb " + verb);
        }
        if (fields.length != wanted) {
            return new Instruction(verb, null, null, null, null, null, null, "BAD_INSTRUCTION", verb + " needs " + wanted + " fields");
        }
        String date = fields[1];
        if (!date.matches("\\d{4}-\\d{2}-\\d{2}")) {
            return new Instruction(verb, date, null, null, null, null, null, "BAD_DATE", date);
        }
        if (verb.equals("REVERSE")) {
            return new Instruction("REVERSE", date, null, null, null, null, fields[2], null, null);
        }
        String amountText = verb.equals("TRANSFER") ? fields[4] : fields[3];
        if (!amountText.matches("\\d+(\\.\\d{1,2})?")) {
            return new Instruction(verb, date, null, null, null, null, null, "BAD_AMOUNT", amountText);
        }
        BigDecimal amount = new BigDecimal(amountText).setScale(2);
        if (amount.signum() <= 0) {
            return new Instruction(verb, date, null, null, null, null, null, "BAD_AMOUNT", amountText);
        }
        String fromId = fields[2];
        String toId = verb.equals("TRANSFER") ? fields[3] : null;
        String currency = verb.equals("TRANSFER") ? fields[5] : null;
        return new Instruction(verb, date, fromId, toId, amount, currency, null, null, null);
    }

    private int fieldCount(String verb) {
        if (verb.equals("TRANSFER")) { return 6; }
        if (verb.equals("WITHDRAW")) { return 4; }
        if (verb.equals("DEPOSIT")) { return 4; }
        if (verb.equals("REVERSE")) { return 3; }
        return -1;
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;

public final class Fees {

    private final Map<String, Map<String, BigDecimal>> byDate = new HashMap<>();

    public BigDecimal feeFor(String tier, BigDecimal amount) {
        if ("STANDARD".equals(tier)) {
            BigDecimal fee = amount.multiply(new BigDecimal("0.005")).setScale(2, RoundingMode.HALF_UP);
            return fee.max(new BigDecimal("0.20"));
        }
        if ("PREMIUM".equals(tier)) {
            BigDecimal fee = amount.multiply(new BigDecimal("0.0025")).setScale(2, RoundingMode.HALF_UP);
            return fee.max(new BigDecimal("0.10")).min(new BigDecimal("5.00"));
        }
        return new BigDecimal("0.00");
    }

    public BigDecimal withdrawFee(String tier) {
        if ("STANDARD".equals(tier)) { return new BigDecimal("1.00"); }
        return new BigDecimal("0.00");
    }

    public BigDecimal dailyLimit(String tier) {
        if ("STANDARD".equals(tier)) { return new BigDecimal("5000.00"); }
        if ("PREMIUM".equals(tier)) { return new BigDecimal("20000.00"); }
        return new BigDecimal("50000.00");
    }

    public BigDecimal overdraft(String tier) {
        if ("PREMIUM".equals(tier)) { return new BigDecimal("500.00"); }
        return new BigDecimal("0.00");
    }

    public void add(String date, String currency, BigDecimal delta) {
        if (delta.signum() == 0) { return; }
        Map<String, BigDecimal> perCurrency = byDate.get(date);
        if (perCurrency == null) { perCurrency = new TreeMap<>(); byDate.put(date, perCurrency); }
        BigDecimal current = perCurrency.get(currency);
        perCurrency.put(currency, current == null ? delta : current.add(delta));
    }

    public Map<String, BigDecimal> forDate(String date) { return byDate.get(date); }
}

package com.rustyledger;

import java.util.ArrayList;
import java.util.List;

public final class AuditLog {

    private final List<String> entries = new ArrayList<>();
    private int seq = 0;

    public void record(String verb, String date, String outcome) {
        seq++;
        entries.add(String.format("%03d  %s %s %s", seq, verb, date, outcome));
    }

    public List<String> lines() { return new ArrayList<>(entries); }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.Map;

public final class DailyReport {

    private DailyReport() {
    }

    public static String build(Map<String, int[]> counts, Fees fees, String date) {
        int[] day = counts.get(date);
        int ok = day == null ? 0 : day[0];
        int rejected = day == null ? 0 : day[1];
        Map<String, BigDecimal> feeMap = fees.forDate(date);
        String feeText = "none";
        if (feeMap != null && !feeMap.isEmpty()) {
            StringBuilder text = new StringBuilder();
            for (Map.Entry<String, BigDecimal> entry : feeMap.entrySet()) {
                if (text.length() > 0) { text.append(", "); }
                text.append(entry.getValue()).append(" ").append(entry.getKey());
            }
            feeText = text.toString();
        }
        return "REPORT " + date + "\nok: " + ok + "\nrejected: " + rejected + "\nfees: " + feeText;
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.math.RoundingMode;

public final class CurrencyConverter {

    private CurrencyConverter() {
    }

    public BigDecimal convert(BigDecimal amount, String from, String to, String tier) {
        BigDecimal inPln = amount.multiply(rate(from)).setScale(4, RoundingMode.HALF_UP);
        BigDecimal result = inPln.divide(rate(to), 4, RoundingMode.HALF_UP);
        if (!"STAFF".equals(tier)) { result = result.multiply(new BigDecimal("0.985")); }
        return result.setScale(2, RoundingMode.HALF_DOWN);
    }

    private BigDecimal rate(String currency) {
        if ("EUR".equals(currency)) { return new BigDecimal("4.30"); }
        if ("USD".equals(currency)) { return new BigDecimal("4.00"); }
        return new BigDecimal("1.00");
    }
}

package com.rustyledger;

import java.math.BigDecimal;

public final class Engine {

    private final Bank bank;

    public Engine(Bank bank) {
        this.bank = bank;
    }

    public String submit(String line) {
        Instruction instruction = new InstructionParser().parse(line);
        if (instruction.rejected()) {
            return fail(instruction);
        }
        String verb = instruction.verb();
        if (verb.equals("TRANSFER")) {
            return doTransfer(instruction);
        }
        if (verb.equals("WITHDRAW")) {
            return doWithdraw(instruction);
        }
        if (verb.equals("DEPOSIT")) {
            return doDeposit(instruction);
        }
        return doReverse(instruction);
    }

    private String fail(Instruction in) {
        if (in.date() == null) {
            bank.audit.record(in.verb(), "????-??-??", "REJECTED " + in.errorCode());
        } else {
            count(in.date(), 1);
            bank.audit.record(in.verb(), in.date(), "REJECTED " + in.errorCode());
        }
        return "REJECTED " + in.errorCode() + ": " + in.errorMessage;
    }

    private String reject(String verb, String date, String problem) {
        int split = problem.indexOf(':');
        String code = problem.substring(0, split);
        String message = problem.substring(split + 2);
        if (date != null) {
            count(date, 1);
        }
        bank.audit.record(verb, date == null ? "????-??-??" : date, "REJECTED " + code);
        return "REJECTED " + code + ": " + message;
    }

    private String accept(String verb, String date, String txId, String extra) {
        count(date, 0);
        bank.audit.record(verb, date, "OK " + txId);
        return "OK " + txId + " " + extra;
    }

    private void count(String date, int slot) {
        int[] day = bank.counts.get(date);
        if (day == null) {
            day = new int[2];
            bank.counts.put(date, day);
        }
        day[slot]++;
    }

    private String doTransfer(Instruction in) {
        String problem = transferProblem(in);
        if (problem != null) {
            return reject("TRANSFER", in.date(), problem);
        }
        Account from = bank.accounts.get(in.fromId());
        Account to = bank.accounts.get(in.toId());
        BigDecimal fee = bank.fees.feeFor(from.tier(), in.amount);
        BigDecimal credited = in.amount;
        if (!from.currency().equals(to.currency())) {
            credited = CurrencyConverter.convert(in.amount, from.currency(), to.currency(), from.tier());
        }
        from.debit(in.amount, fee);
        to.credit(credited);
        bank.used.put(in.fromId() + "|" + in.date(), usedToday(in.fromId(), in.date).add(in.amount));
        String txId = nextTxId();
        bank.txs.put(txId, new Transaction("TRANSFER", in.date, in.fromId, in.toId, in.amount, from.currency(), fee, credited));
        bank.fees.add(in.date, from.currency(), fee);
        return accept("TRANSFER", in.date, txId, "fee=" + fee + " " + from.currency());
    }

    private String transferProblem(Instruction in) {
        Account from = bank.accounts.get(in.fromId);
        Account to = bank.accounts.get(in.toId);
        if (from == null) { return "UNKNOWN_ACCOUNT: " + in.fromId; }
        if (to == null) { return "UNKNOWN_ACCOUNT: " + in.toId; }
        if (in.fromId().equals(in.toId())) { return "SAME_ACCOUNT: cannot transfer to the same account"; }
        if (!from.currency().equals(in.currency())) { return "CURRENCY_MISMATCH: " + in.fromId + " holds " + from.currency; }
        BigDecimal fee = bank.fees.feeFor(from.tier, in.amount);
        return checkLimitAndFunds(in.date, in.fromId, from, in.amount, fee);
    }

    private String doWithdraw(Instruction in) {
        Account account = bank.accounts.get(in.fromId);
        if (account == null) { return reject("WITHDRAW", in.date, "UNKNOWN_ACCOUNT: " + in.fromId); }
        BigDecimal fee = bank.fees.withdrawFee(account.tier);
        String problem = checkLimitAndFunds(in.date, in.fromId, account, in.amount, fee);
        if (problem != null) { return reject("WITHDRAW", in.date, problem); }
        account.debit(in.amount, fee);
        bank.used.put(in.fromId() + "|" + in.date, usedToday(in.fromId, in.date).add(in.amount));
        String txId = nextTxId();
        bank.txs.put(txId, new Transaction("WITHDRAW", in.date, in.fromId, null, in.amount, account.currency, fee, in.amount));
        bank.fees.add(in.date, account.currency, fee);
        return accept("WITHDRAW", in.date, txId, "fee=" + fee + " " + account.currency);
    }

    private String doDeposit(Instruction in) {
        Account account = bank.accounts.get(in.fromId);
        if (account == null) { return reject("DEPOSIT", in.date, "UNKNOWN_ACCOUNT: " + in.fromId); }
        account.credit(in.amount);
        String txId = nextTxId();
        bank.txs.put(txId, new Transaction("DEPOSIT", in.date, in.fromId, null, in.amount, account.currency, new BigDecimal("0.00"), in.amount));
        return accept("DEPOSIT", in.date, txId, "fee=0.00 " + account.currency);
    }

    private String doReverse(Instruction in) {
        Transaction tx = bank.txs.get(in.txId);
        if (tx == null) { return reject("REVERSE", in.date, "UNKNOWN_TX: " + in.txId); }
        String problem = reversalProblem(tx, in);
        if (problem != null) { return reject("REVERSE", in.date, problem); }
        return applyReversal(in, tx);
    }

    private String reversalProblem(Transaction tx, Instruction in) {
        if (!tx.type().equals("TRANSFER")) { return "NOT_REVERSIBLE: " + in.txId + " is a " + tx.type(); }
        if (tx.reversed().equals("Y")) { return "ALREADY_REVERSED: " + in.txId; }
        if (!tx.date().equals(in.date)) { return "REVERSAL_WINDOW: " + in.txId + " was made on " + tx.date; }
        return null;
    }

    private String applyReversal(Instruction in, Transaction tx) {
        Account from = bank.accounts.get(tx.fromId);
        Account to = bank.accounts.get(tx.toId);
        BigDecimal fee = tx.fee();
        BigDecimal back = tx.amount();
        if (from.tier().equals("PREMIUM")) {
            back = back.add(fee);
            if (fee.signum() != 0) { bank.fees.add(in.date, from.currency, fee.negate()); }
        }
        to.reverse(tx.credited());
        from.credit(back);
        tx.markReversed();
        String newId = nextTxId();
        bank.txs.put(newId, new Transaction("REVERSE", in.date, tx.fromId, tx.toId, tx.amount, tx.currency, new BigDecimal("0.00"), tx.credited));
        return accept("REVERSE", in.date, newId, "reversed " + in.txId);
    }

    private String checkLimitAndFunds(String date, String id, Account account, BigDecimal amount, BigDecimal fee) {
        BigDecimal limit = bank.fees.dailyLimit(account.tier);
        BigDecimal overdraft = bank.fees.overdraft(account.tier);
        if (usedToday(id, date).add(amount).compareTo(limit) > 0) {
            return "LIMIT_EXCEEDED: daily limit " + limit + " for " + account.tier;
        }
        BigDecimal needed = amount.add(fee);
        if (account.balance().subtract(needed).compareTo(overdraft.negate()) < 0) {
            return "INSUFFICIENT_FUNDS: balance " + account.balance() + " " + account.currency() + ", needed " + needed + " " + account.currency;
        }
        return null;
    }

    private BigDecimal usedToday(String id, String date) {
        BigDecimal usedAmount = bank.used.get(id + "|" + date);
        return usedAmount == null ? new BigDecimal("0.00") : usedAmount;
    }

    private String nextTxId() {
        bank.txSeq++;
        return String.format("TX-%06d", bank.txSeq);
    }
}

